-- [ENUM] for the available game actions
CREATE TYPE public.game_action AS ENUM (
    'choose',
    'show_question',
    'show_answer'
);

-- [ENUM] for the available game categories
CREATE TYPE public.game_category AS ENUM (
    'animals',
    'architecture',
    'art',
    'board_games',
    'capitals',
    'chemistry',
    'coding',
    'comics',
    'culture',
    'economics',
    'famous_people',
    'food_and_drinks',
    'football',
    'geography',
    'history',
    'languages',
    'league_of_legends',
    'literature',
    'math',
    'movies',
    'music',
    'mythology',
    'nature',
    'physics',
    'politics',
    'science',
    'soccer',
    'space',
    'sports',
    'technology',
    'tv_shows',
    'video_games',
    'pokemon',
    'anime'
);

-- [FUNCTION] to update the updated_at timestamp
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- [TABLE] for the game questions
CREATE TABLE public.game_questions (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    category public.game_category NOT NULL,
    points INTEGER NOT NULL,
    question_de TEXT NOT NULL,
    answer_de TEXT NOT NULL,
    question_en TEXT NOT NULL,
    answer_en TEXT NOT NULL,
    question_it TEXT NOT NULL,
    answer_it TEXT NOT NULL,
    like_count INTEGER NOT NULL DEFAULT 0,
    dislike_count INTEGER NOT NULL DEFAULT 0,
    CONSTRAINT game_questions_pkey PRIMARY KEY (id)
) TABLESPACE pg_default;

-- [COMMENT] on game_questions
COMMENT ON TABLE public.game_questions IS 'The game questions.';

-- Enable RLS for game_questions
ALTER TABLE public.game_questions ENABLE ROW LEVEL SECURITY;

-- [POLICY] Allow selects to everyone
CREATE POLICY "public_game_questions_select" ON "public"."game_questions" FOR
SELECT USING (true);

-- [TRIGGER] to update the updated_at timestamp
CREATE TRIGGER update_game_questions_updated_at_trigger
AFTER UPDATE ON public.game_questions
FOR EACH ROW
EXECUTE FUNCTION update_updated_at();

-- [SEQUENCE] for the game room IDs
CREATE SEQUENCE public.game_room_id_sequence START 0 MINVALUE 0 MAXVALUE 9999 CYCLE;

-- [FUNCTION] to generate a new game room ID
CREATE OR REPLACE FUNCTION gen_room_id()
RETURNS TEXT AS $$
DECLARE
    new_id TEXT;
BEGIN
    LOOP
        -- Get next value from the sequence and pad it with zeros
        new_id := LPAD(nextval('game_room_id_sequence')::TEXT, 4, '0');
        
        -- Check if the ID is not already in use
        IF NOT EXISTS (SELECT 1 FROM public.game_rooms WHERE id = new_id) THEN
            RETURN new_id;
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

-- [TABLE] for the game rooms
CREATE TABLE public.game_rooms (
    id TEXT NOT NULL DEFAULT gen_room_id(),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),
    current_action public.game_action NOT NULL DEFAULT 'choose'::public.game_action,
    CONSTRAINT game_rooms_pkey PRIMARY KEY (id)
) TABLESPACE pg_default;

-- [COMMENT] on game_rooms
COMMENT ON TABLE public.game_rooms IS 'The game rooms.';

-- Enable RLS for game_rooms
ALTER TABLE public.game_rooms ENABLE ROW LEVEL SECURITY;

-- [REALTIME] for game_rooms
ALTER publication supabase_realtime ADD TABLE game_rooms;

-- [POLICY] Allow inserts to everyone
